<script setup lang="ts">
import {ref,onMounted} from 'vue';
import {api,type SetupStatus,type CmsDiscovery,type CmsStatus} from '@/services/api';
import CmsConnectionReport from './CmsConnectionReport.vue';
const props=defineProps<{status:SetupStatus}>();const emit=defineEmits<{complete:[];logout:[]}>();
const username=ref(props.status.username),password=ref(''),confirm=ref(''),base=ref(''),busy=ref(false),discovering=ref(false),error=ref(''),discovery=ref<CmsDiscovery|null>(null),report=ref<CmsStatus|null>(null);
async function discover(){discovering.value=true;error.value='';try{discovery.value=await api.discoverCms();const c=discovery.value.candidates.find(c=>c.id===discovery.value?.recommendedId);if(c){base.value=c.base;report.value=c.report;}}catch(e){error.value=(e as Error).message;}finally{discovering.value=false;}}
async function check(){busy.value=true;error.value='';try{report.value=await api.setupCheck(base.value);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function finish(){if(password.value!==confirm.value){error.value='两次输入的密码不一致。';return;}busy.value=true;error.value='';try{await api.completeSetup(username.value,password.value,base.value);password.value='';confirm.value='';emit('complete');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(discover);
</script>
<template><view class="setup-page"><view class="setup-shell"><view class="setup-intro"><text class="eyebrow">HETUN · OPERATIONS SERVER</text><text class="setup-title">连接你的影视世界</text><text class="setup-description">河豚影视中心 · 首次安装</text><view class="setup-steps"><text>01 独立安装</text><text>02 连接苹果 CMS</text><text>03 发布运营配置</text></view><text class="setup-description">主题中心导出主题 → 本地打包器合并协议基础 APK → App 连接运营服务。</text><text v-if="status.localPreview" class="local-badge">本机测试环境</text></view><view class="setup-form"><view class="setup-heading"><text>内容与账号初始化</text><button :disabled="busy||discovering" @click="discover">{{discovering?'检测中…':'重新发现 CMS'}}</button></view><text class="muted">读取服务配置中的 CMS 地址，检测真实分类和影片接口；也可以手动填写。</text><text v-if="discovery?.multiple" class="muted">检测到多个可用站点，请选择本应用连接的 CMS。</text><button v-for="c in discovery?.candidates" :key="c.id" class="candidate" :class="{selected:base===c.base}" :disabled="busy||!c.base" @click="base=c.base;report=c.report"><view><text>{{c.name}}</text><text class="muted">{{c.base||'未识别域名，请在下面填写'}} · {{c.adapterInstalled?'已发现权限适配文件':'权限适配文件待安装'}}</text></view><text>{{c.report?.ok?'可连接':'待检查'}}</text></button><text v-for="warning in discovery?.warnings" :key="warning" class="muted">{{warning}}</text><text v-if="discovery&&!discovery.candidates.length" class="muted">尚未配置 CMS 地址，请填写你的站点地址并检测连接。</text><label>苹果 CMS 站点地址</label><view class="address-row"><input v-model="base" placeholder="https://你的CMS域名" :disabled="busy" @input="report=null"/><button :disabled="busy||discovering||!base" @click="check">检测连接</button></view><CmsConnectionReport :report="report" :checking="busy" title="实际接口检测"/><view class="account-grid"><view><label>管理员账号</label><input v-model="username" maxlength="40" placeholder="3–40位字母、数字或下划线"/></view><view><label>新密码</label><input v-model="password" password :maxlength="-1" placeholder="密码由你自行设置"/></view><view><label>确认新密码</label><input v-model="confirm" password :maxlength="-1" placeholder="再次输入新密码"/></view></view><text v-if="error" class="failure">{{error}}</text><button class="finish" :disabled="busy||discovering||!base||!username||!password" @click="finish">{{busy?'检测并保存中…':'完成安装，进入运营中心'}}</button><text class="muted">保存前再次检测 CMS。完成后初始密码失效，使用新账号密码登录。</text><button class="exit" :disabled="busy" @click="emit('logout')">退出登录</button></view></view></view></template>
<style scoped>
.setup-page{min-height:100vh;background:var(--studio-bg,#0e131b);color:var(--studio-text,#edf1fa);padding:7vh 5vw;box-sizing:border-box}.setup-shell{max-width:1200px;margin:auto;display:grid;grid-template-columns:0.8fr 1.3fr;gap:60px;align-items:start}.setup-intro{padding-top:45px}.eyebrow{font-size:10px;letter-spacing:3px;color:#a99bf3}.setup-title{display:block;font-size:37px;font-weight:650;margin:26px 0 16px}.setup-description,.muted{display:block;font-size:12px;line-height:1.9;color:var(--studio-muted,#94a0b5)}.setup-steps{display:flex;flex-direction:column;gap:21px;margin:40px 0;color:#b9b1ed;font-size:14px}.setup-form{background:var(--studio-card,#171e2a);border:1px solid var(--studio-border,#2a3345);border-radius:20px;padding:32px}.setup-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:16px;font-size:19px;font-weight:600}.setup-heading button,.address-row button{font-size:11px;white-space:nowrap;padding:10px 14px;background:var(--studio-input,#252d3d);color:inherit;border:1px solid var(--studio-border,#35415a);border-radius:9px}label{display:block;font-size:12px;margin:23px 0 10px}input{height:46px;padding:0 14px;border-radius:9px;background:var(--studio-input,#111823);color:inherit;border:1px solid var(--studio-border,#35415a);font-size:12px;box-sizing:border-box;width:100%}.address-row{display:flex;gap:10px}.address-row input{flex:1;min-width:0}.candidate{display:flex;align-items:center;justify-content:space-between;text-align:left;width:100%;padding:14px;margin-top:12px;font-size:12px;border:1px solid var(--studio-border,#35415a);border-radius:10px;background:transparent;color:inherit}.candidate.selected{border-color:#9a86ed}.candidate>view{min-width:0;overflow-wrap:anywhere}.candidate>text{flex-shrink:0;color:#9bcdad;font-size:11px}.finish{width:100%;margin:24px 0 12px;background:#8b70e8;color:white;font-size:13px;border-radius:10px;padding:14px}.failure{display:block;color:#ffacac;font-size:12px;margin:16px 0}.local-badge{display:block;color:#c7b6fa;font-size:11px;margin-top:30px}.exit{background:transparent;color:var(--studio-muted,#94a0b5);font-size:12px;margin-top:18px}.account-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.account-grid>view:first-child{grid-column:1/-1}button[disabled]{opacity:.5}@media(max-width:850px){.setup-shell{grid-template-columns:1fr;gap:20px}.setup-intro{padding-top:0}.setup-steps{flex-direction:row;margin:20px 0}.setup-title{font-size:27px}.setup-form{padding:22px}.account-grid{grid-template-columns:1fr}}
</style>
